      <div style="background: #f1f5f9; padding: 10px 16px; border-radius: 8px 8px 0 0; border: 1px solid #cbd5e1; border-bottom: none;">
          <div style="display: flex; align-items: center;">
            <div style="flex-shrink: 0; background: #1e293b; color: white; width: 24px; height: 24px; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 13px; margin-right: 12px;">
                <span style="transform: translateY(-1px);">${index + 1}</span>
            </div>
            <h3 style="font-size: 16px; font-weight: 800; color: #1e293b; margin: 0; line-height: 1; transform: translateY(-3px);">${description}</h3>
          </div>
