      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Logo Upload Section */}
        <div className="pb-4 border-b border-gray-100">
          <label className="block text-sm font-medium text-gray-700 mb-2">회사 로고 (선택)</label>
          <div className="flex items-center gap-4">
             {formData.companyLogo ? (
                <div className="relative h-16 bg-gray-50 border rounded-lg overflow-hidden flex items-center justify-center px-2">
                   <img src={formData.companyLogo} className="h-full w-auto object-contain" alt="Company Logo" />
                   <button 
                     type="button"
                     onClick={() => setFormData(prev => ({ ...prev, companyLogo: '' }))}
                     className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl-lg shadow-sm hover:bg-red-600 transition"
                   >
                     <X size={12}/>
